/**
 * MODELO BASE — AFC INOX — ORÇAMENTO
 * Maikon Pinheiro | maio/2026
 *
 * COMO USAR:
 *  1. Preencha as variáveis na seção "DADOS DO ORÇAMENTO"
 *  2. Monte o array `items` com os itens do orçamento
 *  3. Execute: node modelo_orcamento_afc.js
 *  4. Converta o .docx gerado para PDF via LibreOffice
 *
 * REGRAS CRÍTICAS JÁ IMPLEMENTADAS:
 *  - Valor Unitário só aparece na especificação quando quant > 1
 *  - Valor Total só aparece quando há 2 ou mais itens
 *  - Rodapé SEMPRE no footer real do Word (fixo no final de cada página)
 *  - Logo 144x102px no cabeçalho esquerdo
 *  - Linha verde (#2E7D32) apenas no cabeçalho e no último item da tabela
 *  - Sem bordas laterais na tabela
 *  - Entrega sempre: PDF + DOCX
 */

const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, VerticalAlign, ImageRun, Footer,
} = require('docx');
const fs = require('fs');

// ─────────────────────────────────────────
// DADOS DO ORÇAMENTO — editar aqui
// ─────────────────────────────────────────
const CLIENTE     = "Nome do Cliente";       // ex: "Atos Construções"
const ATT         = "Nome do Contato";       // ex: "Dr. Arthur"
const DATA        = "Fortaleza, 18 de Maio de 2026"; // atualizar sempre
const ARQUIVO_OUT = "/home/claude/Proposta_Cliente.docx";

/**
 * Cada item do orçamento:
 * {
 *   num:   "01",          // número do item (string, 2 dígitos)
 *   quant: 1,             // quantidade (número)
 *   spec:  ["linha 1", "linha 2"],  // linhas da especificação
 *                         // NÃO incluir Valor Unitário aqui — será adicionado automaticamente
 *   valor: 4400,          // valor unitário (número, sem formatação)
 * }
 */
const items = [
  {
    num: "01",
    quant: 1,
    spec: ["Bancada em aço inox AISI 304/18.8, medindo 1,00 x 0,60m, com espelho de 7cm, com 01 cuba de 40x34x15cm."],
    valor: 720,
  },
  // Adicione mais itens aqui...
];
// ─────────────────────────────────────────

// LOGO AFC embutida em base64 (fundo transparente) — NAO precisa de arquivo externo.
// Gerada a partir de logo_afc.png em 10/06/2026 (fundo preto -> transparente via PIL).
const LOGO_AFC_B64 = "";
const logoBuffer = Buffer.from(LOGO_AFC_B64, 'base64');

const noBorder  = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };
const greenLine = { style: BorderStyle.SINGLE, size: 8, color: "2E7D32" };

const CONTENT_W  = 9800;
const COL_WIDTHS = [900, 900, 6700, 1300]; // Item | Quant | Especificação | Valor R$

// ── Helpers de texto ──
function txt(text, opts = {})  { return new TextRun({ text, font: "Arial", size: 20, ...opts }); }
function bold(text, opts = {}) { return txt(text, { bold: true, ...opts }); }
function txtSm(text, opts = {})  { return new TextRun({ text, font: "Arial", size: 18, ...opts }); }
function boldSm(text, opts = {}) { return txtSm(text, { bold: true, italics: true, ...opts }); }

function formatMoney(n) {
  return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// ── Células da tabela ──
function headerCell(text, width) {
  return new TableCell({
    borders: { top: greenLine, bottom: greenLine, left: noBorder, right: noBorder },
    width: { size: width, type: WidthType.DXA },
    margins: { top: 80, bottom: 80, left: 80, right: 80 },
    children: [new Paragraph({ children: [txt(text, { bold: true, italics: true })] })]
  });
}

function dataCell(paragraphs, width, isLast = false) {
  return new TableCell({
    borders: {
      top: noBorder,
      bottom: isLast ? greenLine : noBorder,
      left: noBorder, right: noBorder,
    },
    width: { size: width, type: WidthType.DXA },
    margins: { top: 80, bottom: 80, left: 80, right: 80 },
    verticalAlign: VerticalAlign.TOP,
    children: paragraphs,
  });
}

// ── Monta linhas da tabela ──
const totalGeral = items.reduce((sum, it) => sum + (it.valor * it.quant), 0);

const tableRows = [
  new TableRow({
    children: [
      headerCell("Item", COL_WIDTHS[0]),
      headerCell("Quant", COL_WIDTHS[1]),
      headerCell("Especificação", COL_WIDTHS[2]),
      headerCell("Valor R$", COL_WIDTHS[3]),
    ]
  }),
];

items.forEach((item, idx) => {
  const isLast    = idx === items.length - 1;
  const valorItem = item.valor * item.quant;

  // Especificação: adiciona Valor Unitário automaticamente se quant > 1
  const specLines = [...item.spec];
  if (item.quant > 1) {
    specLines.push(`Valor Unitário R$ ${formatMoney(item.valor)}`);
  }

  tableRows.push(new TableRow({
    children: [
      dataCell([new Paragraph({ children: [txt(item.num)] })], COL_WIDTHS[0], isLast),
      dataCell([new Paragraph({ children: [txt(String(item.quant).padStart(2, '0'))] })], COL_WIDTHS[1], isLast),
      dataCell(specLines.map(l => new Paragraph({ children: [txt(l)] })), COL_WIDTHS[2], isLast),
      dataCell([new Paragraph({ children: [txt(formatMoney(valorItem))] })], COL_WIDTHS[3], isLast),
    ]
  }));
});

// ── Documento ──
const doc = new Document({
  sections: [{
    properties: {
      page: {
        size: { width: 11906, height: 16838 }, // A4
        margin: { top: 900, right: 1000, bottom: 1200, left: 1000 }
      }
    },

    // RODAPÉ REAL — fixo no final de cada página
    footers: {
      default: new Footer({
        children: [
          new Paragraph({
            border: { top: { style: BorderStyle.SINGLE, size: 6, color: "888888", space: 4 } },
            alignment: AlignmentType.CENTER,
            children: [boldSm("AFONSO C IND. E COM. DE INOX LTDA")],
            spacing: { before: 100, after: 40 }
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [boldSm("CNPJ: 01.475.443/0001-00  I.E: 06.977.928-7.")],
            spacing: { after: 40 }
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [txtSm("Av. Bernardo Manuel, 8305 – Itaperi")],
            spacing: { after: 40 }
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [txtSm("Fones: (85) 3232.7753 / 9988.3038   E-mail: afcinox@gmail.com")],
            spacing: { after: 40 }
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [txtSm("Fabricamos pias, bancadas, coifas e sistemas de exaustão, corrimões, fogões, peças decorativas, tudo sobre encomenda.")],
            spacing: { after: 0 }
          }),
        ]
      })
    },

    children: [

      // ── CABEÇALHO: Logo | Data/A/Cliente/Att ──
      new Table({
        width: { size: CONTENT_W, type: WidthType.DXA },
        columnWidths: [4000, 5800],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: noBorders,
                width: { size: 4000, type: WidthType.DXA },
                verticalAlign: VerticalAlign.TOP,
                children: [new Paragraph({
                  children: [new ImageRun({ data: logoBuffer, transformation: { width: 144, height: 102 }, type: "png" })]
                })]
              }),
              new TableCell({
                borders: noBorders,
                width: { size: 5800, type: WidthType.DXA },
                verticalAlign: VerticalAlign.TOP,
                children: [
                  new Paragraph({ alignment: AlignmentType.RIGHT, children: [txt(DATA)], spacing: { after: 0 } }),
                  new Paragraph({ alignment: AlignmentType.RIGHT, children: [bold("A")], spacing: { after: 0 } }),
                  new Paragraph({ alignment: AlignmentType.RIGHT, children: [bold(CLIENTE)], spacing: { after: 0 } }),
                  new Paragraph({ alignment: AlignmentType.RIGHT, children: [bold("Att"), txt(`: ${ATT}`)], spacing: { after: 0 } }),
                ]
              }),
            ]
          })
        ]
      }),

      new Paragraph({ children: [], spacing: { before: 200, after: 0 } }),

      // ── TÍTULO ──
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [bold("P R O P O S T A   D E   I N V E S T I M E N T O", { size: 22 })],
        spacing: { before: 0, after: 200 }
      }),

      // ── TABELA ──
      new Table({
        width: { size: CONTENT_W, type: WidthType.DXA },
        columnWidths: COL_WIDTHS,
        rows: tableRows,
      }),

      // ── VALOR TOTAL (só se 2+ itens) ──
      ...(items.length >= 2 ? [
        new Paragraph({
          alignment: AlignmentType.RIGHT,
          children: [bold(`Valor Total R$: ${formatMoney(totalGeral)}`)],
          spacing: { before: 160, after: 0 }
        })
      ] : []),

      new Paragraph({ children: [], spacing: { before: 200, after: 0 } }),

      // ── CONTATO ──
      new Paragraph({
        children: [bold("Contato:"), txt(" Afonso – 99988-3038")],
        spacing: { before: 0, after: 0 }
      }),
      new Paragraph({
        children: [txt("                Maikon – 98730-0482")],
        spacing: { before: 0, after: 300 }
      }),

      // ── ATENCIOSAMENTE ──
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [txt("Atenciosamente,")],
        spacing: { after: 0 }
      }),

    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync(ARQUIVO_OUT, buf);
  console.log(`Gerado: ${ARQUIVO_OUT}`);
});
